 * （工厂依赖 {@code processor}，model 不得反向依赖业务包）。</p>
 */
public record ExtractionStats(String summaryKey, Map<String, String> summaryParams,
                              long elapsedMillis, int totalFiles, int successCount,
                              int failCount, int skipCount, int warnCount,
                              List<WarningDetail> warnDetails, List<FileOutcome> files) {

    public ExtractionStats {
        summaryParams = Map.copyOf(summaryParams);
        warnDetails = List.copyOf(warnDetails);
        files = List.copyOf(files);
    }

    /** Summary warning wrapper; nested warning is rendered only at the presentation boundary. */
    public record WarningDetail(String key, Map<String, String> params, ExtractWarning warning) {
        public WarningDetail { params = Map.copyOf(params); }
    }

    /**
     * 单文件结果快照（{@code processor.FileResult} 的中性映射）：
     * 绝对路径 + 结果类型 + 详情 + 警告列表。
     */
    public record FileOutcome(String path, ExtractOutcome outcome, String messageKey,
                              Map<String, String> messageParams, String messageDetail,
                              List<ExtractWarning> warnings) {
        public FileOutcome {
            messageParams = messageParams == null ? null : Map.copyOf(messageParams);
            warnings = List.copyOf(warnings);
        }
    }
}
